import{_ as e,o as a,c as i,a0 as n}from"./chunks/framework.Zkdr1e1x.js";const g=JSON.parse('{"title":"High-Level Design: Social Network News Feed (Instagram / Twitter)","description":"","frontmatter":{},"headers":[],"relativePath":"hld/instagram.md","filePath":"hld/instagram.md"}'),t={name:"hld/instagram.md"};function l(r,s,o,p,h,c){return a(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="high-level-design-social-network-news-feed-instagram-twitter" tabindex="-1">High-Level Design: Social Network News Feed (Instagram / Twitter) <a class="header-anchor" href="#high-level-design-social-network-news-feed-instagram-twitter" aria-label="Permalink to &quot;High-Level Design: Social Network News Feed (Instagram / Twitter)&quot;">​</a></h1><h2 id="_1-problem-statement-scope" tabindex="-1">1. Problem Statement &amp; Scope <a class="header-anchor" href="#_1-problem-statement-scope" aria-label="Permalink to &quot;1. Problem Statement &amp; Scope&quot;">​</a></h2><p>A massive-scale news feed generation and fan-out system where users can publish posts (images, text) and view a personalized chronological/ranked timeline of posts from users they follow.</p><ul><li><strong>In-Scope</strong>: Post publishing, timeline generation (feed generation), fan-out write vs load (Push vs Pull), pagination, media metadata storage.</li><li><strong>Out-of-Scope</strong>: Machine-learning ranking models, live video broadcasting.</li></ul><hr><h2 id="_2-requirements" tabindex="-1">2. Requirements <a class="header-anchor" href="#_2-requirements" aria-label="Permalink to &quot;2. Requirements&quot;">​</a></h2><h3 id="_2-1-functional-requirements" tabindex="-1">2.1 Functional Requirements <a class="header-anchor" href="#_2-1-functional-requirements" aria-label="Permalink to &quot;2.1 Functional Requirements&quot;">​</a></h3><ul><li><strong>FR-1 (Publish Post)</strong>: Users can upload posts with image URLs and captions.</li><li><strong>FR-2 (News Feed Generation)</strong>: Users can retrieve a chronological feed composed of recent posts from followed users.</li><li><strong>FR-3 (Follow Graph)</strong>: Users can follow/unfollow other users.</li><li><strong>FR-4 (Pagination)</strong>: Cursor-based pagination (<code>limit=20</code>, <code>cursor=&lt;timestamp&gt;</code>).</li></ul><h3 id="_2-2-non-functional-requirements" tabindex="-1">2.2 Non-Functional Requirements <a class="header-anchor" href="#_2-2-non-functional-requirements" aria-label="Permalink to &quot;2.2 Non-Functional Requirements&quot;">​</a></h3><ul><li><strong>Latency</strong>: Fetching feed p99 latency &lt; <strong>200 ms</strong>.</li><li><strong>Availability</strong>: 99.99% read availability.</li><li><strong>Scale</strong>: Support 500M DAU with 100:1 read-to-write ratio.</li></ul><hr><h2 id="_3-high-level-architecture-diagram" tabindex="-1">3. High-Level Architecture Diagram <a class="header-anchor" href="#_3-high-level-architecture-diagram" aria-label="Permalink to &quot;3. High-Level Architecture Diagram&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    User([Mobile / Web Client])</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CDN[Edge CDN]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    LB[API Gateway / Load Balancer]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph Services[&quot;Application Services&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        PostService[Post Service]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        FeedService[Timeline / Feed Service]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        FanoutWorker[Async Fan-out Worker Pool]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        FollowService[Social Graph Service]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph Caches[&quot;Cache Layer&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        FeedCache[(&quot;Redis Feed Cache&lt;br/&gt;(User Timelines - Top 800 Posts)&quot;)]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph DataTier[&quot;Databases&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        GraphDB[(Graph Store / Neo4j / MySQL&lt;br/&gt;Follower Relationships)]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        PostDB[(Cassandra / DynamoDB&lt;br/&gt;Post Data &amp; Media References)]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        MQ{{Apache Kafka&lt;br/&gt;&#39;post-published&#39; Topic}}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    %% Read Path</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    User --&gt;|1. GET /feed| LB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    LB --&gt; FeedService</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    FeedService --&gt;|2. Fetch Timeline| FeedCache</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    FeedCache -.-&gt;|Cache Miss| PostDB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    FeedService --&gt;&gt; User: Return 20 Posts</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    %% Write Path</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    User --&gt;|3. POST /posts| LB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    LB --&gt; PostService</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    PostService --&gt;|4. Save Post| PostDB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    PostService --&gt;|5. Publish Event| MQ</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    %% Fan-out Path</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    MQ --&gt; FanoutWorker</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    FanoutWorker --&gt;|6. Get Followers| GraphDB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    FanoutWorker --&gt;|7. Pre-compute Feed| FeedCache</span></span></code></pre></div><hr><h2 id="_4-fan-out-deep-dive-hybrid-push-vs-pull-strategy" tabindex="-1">4. Fan-Out Deep-Dive: Hybrid Push vs. Pull Strategy <a class="header-anchor" href="#_4-fan-out-deep-dive-hybrid-push-vs-pull-strategy" aria-label="Permalink to &quot;4. Fan-Out Deep-Dive: Hybrid Push vs. Pull Strategy&quot;">​</a></h2><p>A pure <strong>Push (Fan-out-on-write)</strong> model breaks when celebrities with 50M followers post (writing to 50M Redis lists causes catastrophic write amplification). A pure <strong>Pull (Fan-out-on-load)</strong> model causes high read latency.</p><p><strong>The Hybrid Production Solution</strong>:</p><ol><li><strong>Regular Users (&lt; 25,000 followers)</strong>: Use <strong>Fan-out on Write (Push)</strong>. When user posts, workers write post IDs into all followers&#39; Redis timeline lists.</li><li><strong>Celebrity Users (&gt; 25,000 followers)</strong>: Use <strong>Fan-out on Load (Pull)</strong>. Posts are NOT pushed to followers. Instead, when a follower requests their feed, the system fetches their pre-computed regular feed and merges it at read-time with recent posts from the celebrities they follow.</li></ol>`,18)])])}const E=e(t,[["render",l]]);export{g as __pageData,E as default};
